#[derive(Debug, Clone)]
enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Plus(left, right) => {
            let left_optimized = optimize(*left);
            let right_optimized = optimize(*right);
            match (left_optimized, right_optimized) {
                (Exp::Const(0), other) => other, // 0 + x = x
                (other, Exp::Const(0)) => other, // x + 0 = x
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b), // a + b
                (l, r) => Exp::Plus(Box::new(l), Box::new(r)), // no optimization
            }
        }
        Exp::Mult(left, right) => {
            let left_optimized = optimize(*left);
            let right_optimized = optimize(*right);
            match (left_optimized, right_optimized) {
                (Exp::Const(0), _) => Exp::Const(0), // 0 * x = 0
                (_, Exp::Const(0)) => Exp::Const(0), // x * 0 = 0
                (Exp::Const(1), other) => other, // 1 * x = x
                (other, Exp::Const(1)) => other, // x * 1 = x
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b), // a * b
                (l, r) => Exp::Mult(Box::new(l), Box::new(r)), // no optimization
            }
        }
        // Variables and constants are returned unchanged
        Exp::Var(_) | Exp::Const(_) => e,
    }
}

